#include <algorithm>
#include <fstream>
#include <vector>
int main() {
    std::ifstream in("hoofball.in");
    std::ofstream out("hoofball.out");
    int n;
    in >> n;
    std::vector<int> positions(n);
    for (int &x : positions) in >> x;
    std::sort(positions.begin(), positions.end());
    if (n == 1) {
        out << 1 << '\n';
        return 0;
    }
    std::vector<int> destination(n), incoming(n, 0);
    for (int i = 0; i < n; ++i) {
        if (i == 0) destination[i] = 1;
        else if (i == n - 1) destination[i] = n - 2;
        else if (positions[i] - positions[i - 1] <= positions[i + 1] - positions[i])
            destination[i] = i - 1;
        else destination[i] = i + 1;
        ++incoming[destination[i]];
    }
    int answer = 0;
    for (int count : incoming) if (count == 0) ++answer;
    for (int i = 0; i < n; ++i) {
        const int j = destination[i];
        if (i < j && destination[j] == i && incoming[i] == 1 && incoming[j] == 1)
            ++answer;
    }
    out << answer << '\n';
}
