#include <algorithm>
#include <fstream>
#include <vector>
int main() {
    std::ifstream in("taming.in");
    std::ofstream out("taming.out");
    int n;
    in >> n;
    std::vector<int> log(n), forced(n, -1);
    for (int &value : log) in >> value;
    forced[0] = 0;
    for (int day = 0; day < n; ++day) {
        const int value = log[day];
        if (value < 0) continue;
        if (value > day) {
            out << -1 << '\n';
            return 0;
        }
        for (int back = 0; back <= value; ++back) {
            const int index = day - back, counter = value - back;
            if (forced[index] != -1 && forced[index] != counter) {
                out << -1 << '\n';
                return 0;
            }
            forced[index] = counter;
        }
    }
    const int necessary = std::count(forced.begin(), forced.end(), 0);
    const int optional = std::count(forced.begin(), forced.end(), -1);
    out << necessary << ' ' << necessary + optional << '\n';
}
